window.BASE={list:[],
  find(d){return this.list.find(p=>p.dossier===d)},
  // complète seulement les champs vides (ne jamais écraser une information existante)
  fill(x){const p=this.find(x.dossier);if(!p)return this.upsert(x);for(const k in x){if(k==='dossier'||k==='premiere')continue;if(x[k]!==undefined&&x[k]!==''&&x[k]!==null&&(p[k]===undefined||p[k]===''||p[k]===null))p[k]=x[k]}return p},
  remove(d){const i=this.list.findIndex(p=>p.dossier===d);if(i>=0)this.list.splice(i,1)},
  // une autre fiche porte-t-elle déjà ce nom (même nom sans tenir compte de la casse et des accents) ?
  sameName(nom,except){const q=nrmN(nom);if(!q)return null;return this.list.find(p=>p.dossier!==except&&nrmN(p.nom)===q)||null},
  upsert(x){let p=this.find(x.dossier);if(!p){p={dossier:x.dossier,nom:'',sexe:'',assure:null,statut:'',contact:'',proto:'',premiere:x.premiere||today,obs:''};this.list.push(p)}
    for(const k in x){if(x[k]!==undefined&&x[k]!==''&&x[k]!==null&&k!=='premiere')p[k]=x[k]}return p}};
