// ----- Journal d'audit à chaînage de hachage (ajout seul)
function auditList(){try{return JSON.parse(localStorage.getItem(AUK)||'[]')}catch(e){return[]}}
function auditHash(prev,e){return sha256(prev+'|'+e.n+'|'+e.t+'|'+e.u+'|'+e.r+'|'+e.m+'|'+e.a+'|'+e.d)}
function auditAs(u,r,m,a,d){
  const L=auditList(),prev=L.length?L[L.length-1].h:'GENESIS';
  const e={n:L.length+1,t:new Date().toISOString(),u,r,m,a,d:String(d||'')};e.h=auditHash(prev,e);L.push(e);
  try{localStorage.setItem(AUK,JSON.stringify(L))}catch(x){STORAGE_FAIL(x)}
}
window.AUDIT=(m,a,d)=>{if(!LOGGED)return;const u=curUser();auditAs(u.nom,u.role,m,a,d)};
function auditVerify(){const L=auditList();let prev='GENESIS';for(let i=0;i<L.length;i++){const e=L[i];if(e.n!==i+1||auditHash(prev,e)!==e.h)return{ok:false,at:i+1,total:L.length};prev=e.h}return{ok:true,total:L.length}}
