window.printDoc=(title,html)=>{
  const f=document.createElement('iframe');f.setAttribute('style','position:fixed;right:0;bottom:0;width:0;height:0;border:0');document.body.appendChild(f);
  const d=f.contentDocument;d.open();d.write(`<!doctype html><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:13px Arial,sans-serif;margin:24px;color:#000}h1{font-size:18px;margin:10px 0}.t{border-collapse:collapse;width:100%;margin:10px 0}.t td,.t th{border:1px solid #444;padding:5px 8px;text-align:left}.t .r,.r{text-align:right}.m{color:#444}.sign{display:flex;justify-content:space-between;margin-top:70px}.sign div{border-top:1px solid #000;padding-top:4px;width:40%;text-align:center}</style><div style="font-weight:700">Centre de Traitement Ambulatoire de Lambaréné</div>${html}<p class="m" style="margin-top:20px;font-size:11px">Imprimé le ${fdate(today)} par ${esc(curUser().nom)} · Document confidentiel</p>`);d.close();
  setTimeout(()=>{try{f.contentWindow.focus();f.contentWindow.print()}catch(e){}setTimeout(()=>f.remove(),3000)},250);
};
