const pmSub=(s,v)=>String(s).replace(/\{\{(\w+)\}\}/g,(_,k)=>v[k]==null?'':esc(v[k]));
function pmTable(sp,v,rows){
  const cols=sp.cols,W=cols.reduce((a,c)=>a+c[2],0);
  const fs=sp.fs||(cols.length>=14?8:cols.length>=10?9:10.5);
  const head=sp.head?pmSub(sp.head,v):'<tr>'+cols.map(c=>`<th>${pmSub(c[0],v)}</th>`).join('')+'</tr>';
  const body=rows.map(r=>'<tr>'+cols.map(c=>`<td class="${c[3]||'l'}">${esc(r[c[1]]==null?'':r[c[1]])}</td>`).join('')+'</tr>').join('')||`<tr><td colspan="${cols.length}" class="c">Aucune ligne.</td></tr>`;
  const tot=sp.tot?'<tr class="tt">'+sp.tot.map(c=>`<td colspan="${c[1]}" class="${c[2]}">${pmSub(c[0],v)}</td>`).join('')+'</tr>':'';
  return `<table class="g" style="font-size:${fs}px"><colgroup>${cols.map(c=>`<col style="width:${(c[2]/W*100).toFixed(2)}%">`).join('')}</colgroup><thead>${head}</thead><tbody>${body}${tot}</tbody></table>`;
}
