$('bkReset').onclick=()=>confirmBox('Réinitialiser la démonstration','<p>Toutes les données saisies sont remplacées par les données d’exemple. Les mots de passe redeviennent « '+DEFAULT_PW+' ». Le journal d’audit est conservé. Un point de restauration de l’état actuel est créé avant : on peut revenir en arrière.</p>',()=>applyKeys({},'Réinitialisation de la démonstration'),'Tout réinitialiser');
// --- Aide
const HELP={
  commun:[['Se connecter','Choisissez votre nom et saisissez votre mot de passe (l’œil à droite du champ permet de vérifier ce que vous tapez). À la première connexion, le mot de passe initial doit être remplacé (8 caractères minimum, lettres et chiffres). Après 5 échecs, le compte est bloqué 5 minutes. Après 10 minutes sans activité, la session se verrouille.'],['Confidentialité','Les données de santé sont confidentielles. Ne laissez jamais une session ouverte sans surveillance et ne partagez pas votre mot de passe. Chaque action importante est inscrite au journal avec votre nom.'],['Enregistrement','Chaque modification est enregistrée automatiquement, quelques secondes après la saisie. Il n’y a rien à sauvegarder à la main.']],
  Caisse:[['Encaisser','Onglet Accueil : choisissez le dossier, cochez les prestations, validez, puis confirmez. Le reçu est numéroté automatiquement.'],['Consultation externe','Après paiement, la ligne est verrouillée. Seul le médecin-chef peut la déverrouiller (motif obligatoire).'],['Clôture de caisse','Chaque soir : onglet Clôture, comptez les billets et pièces, indiquez le motif d’un éventuel écart, puis clôturez. La journée est alors verrouillée. Imprimez le bordereau.'],['Annuler un reçu','Le motif est obligatoire. Impossible sur une journée clôturée.']],
  Pharmacie:[['Dispenser','Onglet Dispenser : saisissez le n° de dossier, le médicament, la quantité et la durée. Le registre et le stock se mettent à jour. Un nouveau patient reçoit d’abord un ARV. Pour un patient sous plusieurs molécules, toutes les lignes de son schéma se dispensent en une validation.'],['Schéma ARV','Onglet Patients › Modifier : « Changer le schéma » permet de choisir une combinaison en un comprimé ou d’ajouter les molécules une par une. L’historique des changements est conservé.'],['Articles','Onglet Médic. : le pharmacien ajoute les articles de chaque compartiment.'],['Stock et péremptions','Les entrées se font par lot. Les lots qui expirent dans 90 jours sont signalés en haut de page. Les périmés ne sont pas dispensés.'],['Réactifs','Chaque examen encaissé à la caisse consomme des tests ; une boîte est déduite du stock quand tous ses tests sont utilisés.']],
  Laboratoire:[['Examens disponibles','Onglet Examens : la liste reprend tous les examens proposés à la caisse (PVVIH et consultation externe). Quand le réactif d’un examen manque, mettez son interrupteur sur « Indisponible » : l’examen est aussitôt bloqué à la caisse (quelques secondes sur les autres postes). Dès que vous pouvez refaire l’examen, remettez « Disponible ». L’historique garde l’heure et l’utilisateur de chaque changement. Le stock enregistré ne bloque plus rien : seul ce choix compte.'],['Comptage du stock','Onglet Comptage, en fin de semaine ou de quinzaine : choisissez Réactifs ou Consommables (gants, aiguilles…), saisissez le nombre de boîtes comptées, puis enregistrez. Le logiciel affiche le début (dernier comptage), les entrées depuis, l’écart avec son stock et ce qui a réellement été consommé, ratés compris. Les écarts corrigent le stock et le comptage devient le nouveau début.'],['Stock','Onglet Stock : « Enregistrer une entrée » pour chaque réception (chaque entrée forme son propre lot, avec son n° de lot et sa péremption). En cas d’erreur, « Modifier » sur la ligne du lot corrige l’article, le lot, la quantité ou la péremption, avec un motif obligatoire. Une entrée en stock lève aussi le blocage « terminé » du réactif.'],['Ajouter un article','Onglet Médic. : si un réactif ou un consommable n’existe pas encore, ajoutez-le avant d’enregistrer son entrée.']],
  IDEP:[['Saisie IDEP','Compte limité : il ne voit que la saisie de la consultation externe, sur la consultation IDEP. La saisie est la même que dans la gestion de la caisse.']],
  RH:[['Factures CNAMGS','Une facture comporte 10 lignes au plus. Validez-la pour la classer, puis constituez le récapitulatif par fonds et par nature. Une facture validée reste modifiable ou supprimable (motif obligatoire) tant que l’année n’est pas clôturée.'],['État de la dette','Saisissez l’historique mois par mois si besoin ; le report d’une année à l’autre est automatique. Clôturez l’année quand tout est contrôlé ; seul le médecin-chef peut la rouvrir.']],
  PTME:[['Suivi PTME','Ajoutez une fiche par mère. Les dates sont contrôlées (accouchement après début de grossesse, PCR après accouchement). Export Excel.']],
  'Médecin-chef':[['Droits du médecin-chef','Accès à tous les modules, au journal d’audit, aux tarifs et aux remplacements (Paramètres). Lui seul peut déverrouiller une consultation payée, rouvrir une journée de caisse ou une année de dette.'],['Remplacements et tarifs','Paramètres : désigner un remplaçant à la caisse ou à la pharmacie, modifier les prix des prestations.']],
  Administrateur:[['Rôle de l’administrateur','Il voit tous les modules du menu, mais il ne peut ouvrir que les Paramètres (et le Guide) : la caisse, la pharmacie, les RH, la PTME, le laboratoire, la base patients, le journal d’audit et les sauvegardes lui sont fermés.'],['Utilisateurs et mots de passe','Paramètres › Utilisateurs : modifier le nom et le prénom de la personne qui tient chaque poste. Paramètres › Mots de passe : réinitialiser un mot de passe oublié (nouveau mot de passe initial « '+DEFAULT_PW+' », à changer à la première connexion).']]
};
function renderHelp(){
  const r=curUser().role,sec=[...HELP.commun,...(r==='Médecin-chef'?['Caisse','Pharmacie','RH','PTME','Médecin-chef'].flatMap(k=>HELP[k]):(HELP[r]||[]))];
  $('helpBody').innerHTML=`<p class="muted">Aide pour le rôle : <b>${esc(r)}</b><br>Toutes les cartes du menu sont visibles ; celles des autres postes sont grisées et ne s’ouvrent pas.</p>`+sec.map(([t,x])=>`<div class="card"><h2>${esc(t)}</h2><p style="margin:0;white-space:pre-line">${esc(x)}</p></div>`).join('');
}
// ----- Guide complété : une section par module (à quoi il sert, étapes, droits)
const GUIDE={
  Patients:[['Base patients','Une seule fiche par n° de dossier, partagée par la caisse, la pharmacie et la PTME.\nÉtapes : ouvrez « Base patients », recherchez un nom ou un n° de dossier, cliquez sur une ligne pour ouvrir la fiche, complétez le nom, le contact ou le rendez-vous, puis « Enregistrer ». La fiche se ferme et la modification est répercutée dans tous les modules.\nDroits : médecin-chef, caisse et pharmacie seulement.'],['Créer une fiche','Les fiches sont créées automatiquement à la première saisie (caisse ou pharmacie). En pharmacie, « Patients » › « + Nouvelle fiche » crée une fiche avec son n° de dossier : le formulaire se ferme dès la validation.']],
  'Journal d’audit':[['Journal d’audit','Historique en ajout seul de toutes les actions : qui, quel module, quoi, quand, avec une empreinte SHA-256 qui détecte toute retouche.\nÉtapes : ouvrez « Journal d’audit », filtrez par module ou recherchez un nom, cliquez sur « Vérifier l’intégrité » (le journal doit être intact), « Exporter en CSV » pour archiver.\nDroits : médecin-chef seulement.']],
  Sauvegarde:[['Sauvegardes','Les données sont enregistrées sur le serveur à chaque modification ; les copies complètes (JSON) se téléchargent par l’administrateur informatique, et la restauration se fait sur le serveur avec restaurer.php.\nÉtapes : « Sauvegardes » › « Télécharger une copie complète ». Cette copie contient des données de santé : support protégé, suppression après usage.\nDroits : médecin-chef seulement.']],
  CNAMGS:[['Factures CNAMGS','Saisie des factures de 10 lignes au plus, puis récapitulatif par fonds et par nature.\nÉtapes : choisissez le fonds et la nature, saisissez le n° de facture, la date, puis remplissez les lignes (N° de feuilles, nom et prénom, n° assuré, montant total, part patient ; le remboursement se calcule). Naviguez au clavier avec ← → ↑ ↓, validez avec « Valider la facture », puis constituez le récapitulatif.\nDroits : RH, CNAMGS et médecin-chef.'],['Autocomplétion des noms','Dans la colonne « Noms et prénoms », la saisie propose les noms déjà écrits plus haut dans le tableau : Entrée ou clic pour accepter, ↑ ↓ pour parcourir les suggestions, Échap pour les fermer.']],
  Caisse:[['Gestion de la caisse','Encaissement des prestations PVVIH, des consultations externes (IDEP compris), des examens et des certificats, avec reçus patient et caisse.\nÉtapes : choisissez le dossier, cochez les prestations, saisissez le montant encaissé (obligatoire sauf patient exonéré), validez puis confirmez ; le reçu s’imprime ou se ferme. La clôture de caisse se fait chaque soir avec le bordereau.\nDroits : caisse, IDEP, médecin-chef. Le nom du caissier connecté figure sur chaque reçu.']],
  Pharmacie:[['Dispensation','Étapes : onglet « Dispenser », n° de dossier, quantité et durée, puis « Valider la dispensation » ; le formulaire se vide aussitôt pour le patient suivant. Le registre et le stock se mettent à jour.\nDroits : pharmacie et médecin-chef.'],['Registre et stock','Le registre ARV se remplit tout seul. Cliquez sur une case de mois pour corriger la quantité de boîtes ou la durée : le stock du lot est ajusté (une baisse remet en stock, une hausse est débitée), avec un message clair si la hausse dépasse le stock du lot. Chaque modification est inscrite au journal avec l’ancienne et la nouvelle valeur.\nOnglet « Stock » : les entrées se font par lot ; « Contrôle par lot » compare chaque lot au comptage physique et corrige le lot concerné (exemple 24 en stock, 25 comptés : +1 rendu au lot).']],
  Laboratoire:[['Réactifs et patients','Onglet « Examens » : rendre un examen indisponible bloque aussitôt la caisse. Onglet « Patients » : tous les patients dont des examens ont été sélectionnés à la caisse apparaissent automatiquement avec leurs examens ; les colonnes se trient d’un clic et la recherche filtre par nom.\nDroits : laboratoire (réactifs, consommables, patients), médecin-chef.']],
  PTME:[['Suivi PTME','Étapes : « + Nouvelle fiche », n° PTME, dossier de la mère, dates de grossesse et d’accouchement, protocole et dispensation ; « Enregistrer » ferme le formulaire et met à jour la base patients. Export Excel et Word paysage disponibles.\nDroits : PTME et médecin-chef.']],
  'RH':[['Personnel','Fiches du personnel, congés et contrats. « Enregistrer » ferme la fiche et actualise la liste.\nDroits : RH, médecin-chef.'],['CNAMGS','Factures de 10 lignes, récapitulatifs et état de la dette (voir la section CNAMGS).\nDroits : RH, CNAMGS, médecin-chef.']],
  Paramètres:[['Paramètres','Utilisateurs par poste (créer, renommer, réinitialiser un mot de passe, désactiver) et tarifs de la caisse.\nDroits : administrateur (utilisateurs) et médecin-chef (utilisateurs des postes, tarifs).']]
};
const GUIDE_BY_ROLE={'Médecin-chef':['Patients','Caisse','Pharmacie','Laboratoire','CNAMGS','RH','PTME','Journal d’audit','Sauvegarde','Paramètres'],Administrateur:['Paramètres'],Caisse:['Caisse'],IDEP:['IDEP'],Pharmacie:['Pharmacie'],Laboratoire:['Laboratoire'],'RH':['RH','CNAMGS'],CNAMGS:['CNAMGS','RH'],PTME:['PTME']};
renderHelp=function(){
  const r=curUser().role;
  const sec=[...HELP.commun],seen=new Set(HELP.commun.map(x=>x[0]));
  const add=x=>{if(!seen.has(x[0])){seen.add(x[0]);sec.push(x)}};
  (GUIDE_BY_ROLE[r]||[]).forEach(k=>{(GUIDE[k]||HELP[k]||[]).forEach(add)});
  (HELP[r]||[]).forEach(add);
  $('helpBody').innerHTML=`<p class="muted">Aide pour le rôle : <b>${esc(r)}</b><br>Toutes les cartes du menu sont visibles ; celles des autres postes sont grisées et ne s’ouvrent pas.</p>`+sec.map(([t,x])=>`<div class="card"><h2>${esc(t)}</h2><p style="margin:0;white-space:pre-line">${esc(x)}</p></div>`).join('');
};
// --- Paramètres : utilisateurs par poste (plusieurs comptes par service)
const POSTES=['Caisse','IDEP','Pharmacie','RH','CNAMGS','PTME','Laboratoire'];
let pTab='U';
function setPTab(t){pTab=t;$('pgU').hidden=t!=='U';$('pgT').hidden=t!=='T';$('ptU').className='btn sm'+(t==='U'?'':' ghost');$('ptT').className='btn sm'+(t==='T'?'':' ghost')}
$('ptU').onclick=()=>setPTab('U');$('ptT').onclick=()=>setPTab('T');
addEye($('nuPw'));
const pwRule=n=>(n.length<8||!/[A-Za-z]/.test(n)||!/\d/.test(n))?'Au moins 8 caractères, avec des lettres et des chiffres.':'';
const fullName=(f,l)=>(f+' '+l).trim().replace(/\s+/g,' ');
const nameTaken=(nom,exceptId)=>PARAMS.users.some(x=>x.id!==exceptId&&x.nom.toLowerCase()===nom.toLowerCase());
const canUser=u=>{const r=curUser().role;return r==='Administrateur'||(r==='Médecin-chef'&&POSTES.includes(u.role))};
const canReset=u=>canUser(u)||(curUser().role==='Médecin-chef'&&u.role==='Administrateur');
const lastActive=u=>(u.role==='Administrateur'||u.role==='Médecin-chef')&&PARAMS.users.filter(x=>x.role===u.role&&x.actif!==false).length<2;
function sheetOpen(h,focus){$('sheet').innerHTML=h;$('modal').hidden=false;const e=focus&&$(focus);if(e)e.focus()}
function editUser(id){
  const u=PARAMS.users.find(x=>x.id===id);if(!u||!canUser(u))return;
  const poste=POSTES.includes(u.role);
  sheetOpen(`<h3>Modifier l’utilisateur</h3>${poste?`<label for="eu_role">Poste</label><select id="eu_role">${POSTES.map(p=>`<option${p===u.role?' selected':''}>${p}</option>`).join('')}</select>`:`<p class="muted" style="margin:0 0 6px">Poste : ${esc(u.role)}</p>`}<label for="eu_last">Nom</label><input type="text" id="eu_last" value="${esc(u.last||'')}" autocomplete="off"><label for="eu_first">Prénom</label><input type="text" id="eu_first" value="${esc(u.first||'')}" autocomplete="off"><div class="err" id="eu_err" role="alert" style="color:var(--red);font-size:.88rem;min-height:1.2em;margin-top:6px"></div><div class="acts"><button class="btn ghost" id="eu_no">Annuler</button><button class="btn" id="eu_ok">Enregistrer</button></div>`,'eu_last');
  $('eu_no').onclick=()=>$('modal').hidden=true;
  $('eu_ok').onclick=()=>{const l=$('eu_last').value.trim(),f=$('eu_first').value.trim(),nom=fullName(f,l);
    if(!l){$('eu_err').textContent='Le nom est obligatoire.';return}
    if(nameTaken(nom,u.id)){$('eu_err').textContent='Un utilisateur porte déjà ce nom : le journal ne pourrait pas les distinguer.';return}
    const old=u.nom+' ('+u.role+')';u.last=l;u.first=f;u.nom=nom;if(poste)u.role=$('eu_role').value;
    shellSave();AUDIT('Paramètres','Utilisateur modifié',old+' → '+u.nom+' ('+u.role+')');$('modal').hidden=true;renderParams();refreshWho();toast('Utilisateur modifié')};
}
function resetPw(id){
  const u=PARAMS.users.find(x=>x.id===id);if(!u||!canReset(u))return;
  sheetOpen(`<h3>Nouveau mot de passe provisoire</h3><p class="muted" style="margin-top:0">${esc(u.nom)} (${esc(u.role)}) devra le remplacer à sa prochaine connexion.</p><label for="rp_pw">Mot de passe provisoire</label><input type="password" id="rp_pw" autocomplete="new-password"><div class="err" id="rp_err" role="alert" style="color:var(--red);font-size:.88rem;min-height:1.2em;margin-top:6px"></div><div class="acts"><button class="btn ghost" id="rp_no">Annuler</button><button class="btn" id="rp_ok">Enregistrer</button></div>`,'rp_pw');
  addEye($('rp_pw'));
  $('rp_no').onclick=()=>$('modal').hidden=true;
  $('rp_ok').onclick=()=>{const n=$('rp_pw').value,m=pwRule(n);if(m){$('rp_err').textContent=m;return}
    u.salt=rnd(8);u.hash=hashPw(u.salt,n);u.must=true;u.fails=0;u.lock=0;shellSave();AUDIT('Paramètres','Mot de passe réinitialisé',u.nom);$('modal').hidden=true;renderParams();toast('Mot de passe provisoire enregistré pour '+u.nom)};
}
function toggleUser(id){
  const u=PARAMS.users.find(x=>x.id===id);if(!u||!canUser(u))return;
  if(u.id===PARAMS.current){toast('Vous ne pouvez pas désactiver votre propre compte');return}
  const off=u.actif!==false;
  if(off&&lastActive(u)){toast('Il faut garder au moins un compte actif pour ce poste');return}
  u.actif=!off;shellSave();AUDIT('Paramètres',off?'Utilisateur désactivé':'Utilisateur réactivé',u.nom+' ('+u.role+')');renderParams();toast(off?'Compte désactivé : connexion impossible':'Compte réactivé');
}
$('nuAdd').onclick=()=>{
  const l=$('nuLast').value.trim(),f=$('nuFirst').value.trim(),pw=$('nuPw').value,role=$('nuPoste').value,nom=fullName(f,l),E=$('nuErr');
  if(!l){E.textContent='Le nom est obligatoire.';return}
  if(nameTaken(nom)){E.textContent='Un utilisateur porte déjà ce nom : ajoutez le prénom ou une précision.';return}
  const m=pwRule(pw);if(m){E.textContent=m;return}
  const salt=rnd(8);PARAMS.users.push({id:PARAMS.uid++,nom,last:l,first:f,role,actif:true,salt,hash:hashPw(salt,pw),must:true,fails:0,lock:0});
  shellSave();AUDIT('Paramètres','Utilisateur créé',role+' : '+nom);E.textContent='';['nuLast','nuFirst','nuPw'].forEach(i=>$(i).value='');
  if($('nuPw')._eyeReset)$('nuPw')._eyeReset();
  renderParams();toast('Compte créé pour '+nom+' ('+role+') : mot de passe à changer à la première connexion');
};
const _rp=renderParams;renderParams=function(){
  _rp();
  try{renderExtTarifs()}catch(e){}
  const r=curUser().role,chef=r==='Médecin-chef';
  $('ptT').hidden=!chef;if(!chef&&pTab==='T')setPTab('U');else setPTab(pTab);
  $('uAddCard').hidden=!(r==='Administrateur'||chef);
  const lk=(a,id,t)=>`<button data-${a}="${id}" style="background:none;border:0;color:var(--blue);cursor:pointer;font:inherit;text-decoration:underline;margin-right:8px">${t}</button>`;
  const order=['Médecin-chef','Administrateur',...POSTES];
  const L=PARAMS.users.slice().sort((a,b)=>order.indexOf(a.role)-order.indexOf(b.role)||a.nom.localeCompare(b.nom));
  $('uT').innerHTML='<thead><tr><th>Poste</th><th>Nom</th><th>Prénom</th><th>État</th><th></th></tr></thead><tbody>'+L.map(u=>`<tr${u.actif===false?' class="muted"':''}><td><span class="pill">${esc(u.role)}</span></td><td>${esc(u.last||u.nom)}</td><td>${u.first?esc(u.first):'<span class="muted">—</span>'}</td><td>${u.actif===false?'Désactivé':u.must?'Mot de passe provisoire':'Actif'}</td><td>${canUser(u)?lk('ue',u.id,'Modifier'):''}${canReset(u)?lk('up',u.id,'Mot de passe'):''}${canUser(u)&&u.id!==PARAMS.current?lk('ut',u.id,u.actif===false?'Réactiver':'Désactiver'):''}</td></tr>`).join('')+'</tbody>';
  $('uT').querySelectorAll('[data-ue]').forEach(b=>b.onclick=()=>editUser(+b.dataset.ue));
  $('uT').querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>resetPw(+b.dataset.up));
  $('uT').querySelectorAll('[data-ut]').forEach(b=>b.onclick=()=>toggleUser(+b.dataset.ut));
};
// --- Démarrage
if(!window.crypto||!crypto.subtle){$('bkPass').disabled=true;$('bkPass2').disabled=true;$('bkPass').placeholder='Chiffrement indisponible ici'}
['lgPw','chOld','chNew','chNew2','bkPass','bkPass2'].forEach(id=>addEye($(id)));
show('home');loginFill('');
window.NOSAVE=false;
// ----- Mode serveur : réactions aux changements venus d'autres postes, fusions, état de l'enregistrement
(function(){
  const MODKEY={'cta.caisse.v1':'caisse','cta.rh.v1':'rh','cta.pharma.v1':'pharma','cta.ptme.v1':'ptme'};
  const hh=t=>{const d=new Date(t);return d.toTimeString().slice(0,8)};
  window.SAVED=()=>{};
  window.STORAGE_FAIL=e=>{const x=$('saveSt');if(x){x.textContent='ATTENTION : '+(e&&e.message||'enregistrement impossible')+'.';x.style.color='var(--red)'}};
  CTA_HOOKS.onState=s=>{
    const x=$('saveSt');if(!x)return;
    if(s.err){x.textContent='ATTENTION : '+s.err+(s.pending?' ('+s.pending+' en attente)':'');x.style.color='var(--red)'}
    else{x.textContent=(s.pending?'Enregistrement sur le serveur…':'Données enregistrées sur le serveur à '+hh(s.last||Date.now()));x.style.color=''}
  };
  function banner(msg,btn,fn){
    let b=document.getElementById('ctaBanner');
    if(!b){b=document.createElement('div');b.id='ctaBanner';b.setAttribute('role','alert');b.setAttribute('style','position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:9000;background:#0b3d2b;color:#fff;padding:12px 16px;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,.3);display:flex;gap:12px;align-items:center;max-width:92vw;font:600 .95rem system-ui,Segoe UI,Arial,sans-serif');document.body.appendChild(b)}
    b.innerHTML='<span></span>';b.firstChild.textContent=msg;
    if(btn){const k=document.createElement('button');k.textContent=btn;k.setAttribute('style','border:0;border-radius:9px;padding:8px 14px;font:700 .9rem inherit;background:#f5c542;color:#1b1b1b;cursor:pointer');k.onclick=()=>{b.remove();fn()};b.appendChild(k)}
    else setTimeout(()=>b.remove(),9000);
  }
  const reload=m=>{frames[m].srcdoc=dec(M[m])};
  const visible=m=>window.curMod===m&&!$('view').hidden;
  // module modifié depuis un autre poste
  CTA_HOOKS.onRemote=(k,adopt)=>{
    if(k==='cta.audit.v1'){adopt(k);return}
    if(k==='cta.shell.v1'){
      adopt(k);
      try{const o=JSON.parse(localStorage.getItem(k));
        const mine=new Map(BASE.list.map(b=>[b.dossier,b])),srv=new Set((o.base||[]).map(b=>b.dossier));
        BASE.list=(o.base||[]).concat(BASE.list.filter(b=>!srv.has(b.dossier)));
        if(Array.isArray(o.labo)){const ids=new Set(LABREQ.map(r=>r.id));LABREQ=o.labo.concat(LABREQ.filter(r=>!o.labo.some(x=>x.id===r.id)))}
        if(o.users&&o.users.length){const cur=PARAMS.current;PARAMS.users=o.users;PARAMS.uid=o.uid||PARAMS.uid;PARAMS.remps=o.remps||[];PARAMS.rid=o.rid||PARAMS.rid;PARAMS.current=PARAMS.users.some(u=>u.id===cur)?cur:PARAMS.users[0].id}
      }catch(e){}
      return;
    }
    const m=MODKEY[k];if(!m)return;
    if(visible(m))banner('Un autre poste a modifié ces données.','Actualiser',()=>{adopt(k);reload(m)});
    else{adopt(k);reload(m)}
  };
  // conflit au moment d'enregistrer : le module est actualisé, la dernière action est à refaire
  CTA_HOOKS.onConflict=k=>{
    const m=MODKEY[k];if(!m)return;
    reload(m);
    banner('Un autre poste venait de modifier ces données : la page a été actualisée. Refaites votre dernière action.');
  };
  // fusions automatiques
  CTA_HOOKS.merge['cta.shell.v1']=(loc,srv)=>{
    const L=JSON.parse(loc),S=JSON.parse(srv),ld=new Set((L.base||[]).map(b=>b.dossier));
    const out=Object.assign({},S);out.base=(L.base||[]).concat((S.base||[]).filter(b=>!ld.has(b.dossier)));
    if(Array.isArray(L.labo)){const seen=new Set((S.labo||[]).map(r=>r.id));out.labo=(S.labo||[]).concat(L.labo.filter(r=>!seen.has(r.id))).slice(-1000)}
    return JSON.stringify(out);
  };
  CTA_HOOKS.merge['cta.audit.v1']=(loc,srv)=>{
    const L=JSON.parse(loc),S=JSON.parse(srv),seen=new Set(S.map(e=>e.h));
    const extra=L.filter(e=>!seen.has(e.h)&&!S.some(x=>x.t===e.t&&x.u===e.u&&x.a===e.a&&x.d===e.d));
    // seules les entrées locales ajoutées après la dernière entrée commune sont rattachées à la chaîne du serveur
    const common=L.findIndex((e,i)=>!S[i]||S[i].h!==e.h);
    const mine=(common<0?[]:L.slice(common)).filter(e=>extra.includes(e));
    let prev=S.length?S[S.length-1].h:'GENESIS';
    mine.forEach(e=>{const c=Object.assign({},e);c.n=S.length+1;c.h=auditHash(prev,c);S.push(c);prev=c.h});
    return JSON.stringify(S);
  };
  setInterval(shellSave,500);
  const st=document.getElementById('saveSt');if(st)st.textContent='Connecté au serveur de données…';
  window.addEventListener('pagehide',()=>{try{CTA_STORE.flush()}catch(e){}});
})();
// ----- Mode serveur : comptes, droits, journal et numéros de reçu sont tenus par le serveur
(function(){
  const U=window.CTA_USER,HD={'X-CTA':'1','Content-Type':'text/plain'};
  const post=async(a,b)=>{const r=await fetch('api.php?a='+a,{method:'POST',headers:HD,body:JSON.stringify(b||{})});return r.json()};
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  // session ouverte par le serveur : plus d'écran de connexion dans l'application
  PARAMS.current=U.id;LOGGED=true;$('login').hidden=true;$('login').dataset.forced='';refreshWho();applyRights();show('home');
  // journal : le serveur inscrit l'acteur d'après la session
  const Q=[];let sending=false;
  async function sendAudit(){
    if(sending||!Q.length)return;sending=true;
    while(Q.length){const items=Q.slice(0,50);
      try{const r=await post('audit',{items});if(r.auth)break;Q.splice(0,items.length)}catch(e){await sleep(3000)}}
    sending=false;
  }
  window.AUDIT=(m,a,d)=>{if(!LOGGED)return;Q.push({m,a,d:String(d||'')});sendAudit()};
  auditAs=function(u,r,m,a,d){Q.push({m,a,d:String(d||'')});sendAudit()};
  const lastRead={};
  window.AUDIT_READ=(mod,dossier)=>{const k=mod+'|'+dossier,t=Date.now();if(lastRead[k]&&t-lastRead[k]<60000)return;lastRead[k]=t;window.AUDIT('Dossier','Consultation · '+mod,String(dossier))};
  addEventListener('pagehide',()=>{if(Q.length){try{fetch('api.php?a=audit',{method:'POST',keepalive:true,headers:HD,body:JSON.stringify({items:Q})})}catch(e){}}});
  // numéro de reçu attribué par le serveur (jamais de doublon, même avec plusieurs caisses)
  window.CTA_SEQ=nom=>{
    let r=null;
    try{const x=new XMLHttpRequest();x.open('POST','api.php?a=seq',false);x.setRequestHeader('X-CTA','1');x.send('{}');r=JSON.parse(x.responseText)}catch(e){}
    if(!r||!r.ok){alert('Impossible d’attribuer le numéro de reçu ('+(r&&r.err?r.err:'serveur injoignable')+').\nAucun reçu n’a été émis : réessayez.');throw new Error('Numéro de reçu indisponible')}
    return r.n;
  };
  // déconnexion
  lockSession=async function(msg,why){
    try{flushAll();await CTA_STORE.flush();while(Q.length&&!sending){await sendAudit()}}catch(e){}
    try{await post('logout',{})}catch(e){}
    window.onbeforeunload=null;location.reload();
  };
  // session expirée pendant le travail : les modifications restent en attente et repartent après reconnexion
  let authBanner=false;
  CTA_HOOKS.onAuth=()=>{
    if(authBanner)return;authBanner=true;
    const b=document.createElement('div');b.setAttribute('role','alert');
    b.setAttribute('style','position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:9000;background:#7a1d16;color:#fff;padding:12px 16px;border-radius:12px;display:flex;gap:12px;align-items:center;max-width:92vw;font:600 .95rem system-ui,Segoe UI,Arial,sans-serif');
    b.innerHTML='<span>Votre session a expiré : vos dernières modifications sont en attente.</span>';
    const k=document.createElement('button');k.textContent='Se reconnecter';k.setAttribute('style','border:0;border-radius:9px;padding:8px 14px;font:700 .9rem inherit;background:#f5c542;color:#1b1b1b;cursor:pointer');
    k.onclick=()=>window.open('index.php','_blank');b.appendChild(k);document.body.appendChild(b);
    const t=setInterval(async()=>{try{const r=await (await fetch('api.php?a=session',{headers:{'X-CTA':'1'}})).json();
      if(r.ok&&r.user){clearInterval(t);if(r.user.id!==U.id){location.reload()}else{b.remove();authBanner=false;CTA_STORE.flush()}}}catch(e){}},4000);
  };
  // mot de passe : changement par le serveur
  $('lgForm').onsubmit=ev=>{if(ev&&ev.preventDefault)ev.preventDefault();if(!$('lgCh').hidden)$('chGo').click()};
  $('chGo').onclick=async()=>{
    const o=$('chOld').value,n=$('chNew').value,n2=$('chNew2').value,E=$('chErr');
    if(n!==n2){E.textContent='Les deux saisies ne correspondent pas.';return}
    try{const r=await post('chpw',{old:o,new:n});if(!r.ok){E.textContent=r.err||'Échec.';return}$('login').hidden=true;toast('Mot de passe modifié')}catch(e){E.textContent='Serveur injoignable.'}
  };
  $('myAcc').onclick=()=>{$('login').dataset.forced='';loginFill('Changer mon mot de passe','change')};
  const _rp0=resetPw;
  resetPw=function(id){
    _rp0(id);const u=PARAMS.users.find(x=>x.id===id),ok=$('rp_ok');if(!ok||!u)return;
    ok.onclick=async()=>{const n=$('rp_pw').value,m=pwRule(n);if(m){$('rp_err').textContent=m;return}
      try{const r=await post('user_reset',{id,pw:n});if(!r.ok){$('rp_err').textContent=r.err||'Refusé par le serveur.';return}}catch(e){$('rp_err').textContent='Serveur injoignable.';return}
      u.must=true;$('modal').hidden=true;renderParams();toast('Mot de passe provisoire enregistré pour '+u.nom)};
  };
  $('nuAdd').onclick=async()=>{
    const l=$('nuLast').value.trim(),f=$('nuFirst').value.trim(),pw=$('nuPw').value,role=$('nuPoste').value,E=$('nuErr');
    if(!l){E.textContent='Le nom est obligatoire.';return}
    const m=pwRule(pw);if(m){E.textContent=m;return}
    let r;try{r=await post('user_add',{last:l,first:f,role,pw})}catch(e){E.textContent='Serveur injoignable.';return}
    if(!r.ok){E.textContent=r.err||'Refusé par le serveur.';return}
    PARAMS.users.push(r.user);PARAMS.uid=Math.max(PARAMS.uid,r.user.id+1);shellSave();
    E.textContent='';['nuLast','nuFirst','nuPw'].forEach(i=>$(i).value='');if($('nuPw')._eyeReset)$('nuPw')._eyeReset();
    renderParams();toast('Compte créé pour '+r.user.nom+' ('+role+') : mot de passe à changer à la première connexion');
  };
  // plus aucune copie de données de santé dans le navigateur
  mirror=async function(){};snapshotNow=async function(){};fileExport=async function(){};
  renderBackup=async function(){
    const w=document.querySelector('#backup .wrap');
    w.innerHTML='<div class="card"><h2>Sauvegardes du serveur</h2><p class="muted" style="margin-top:0">Les données sont enregistrées sur le serveur à chaque modification. Les sauvegardes quotidiennes chiffrées sont faites par la tâche planifiée du serveur (voir LISEZ-MOI) ; la restauration complète se fait sur le serveur, par l’administrateur informatique, avec <b>restaurer.php</b>.</p><a class="btn" style="display:inline-block;text-align:center;text-decoration:none;padding:12px 18px" href="api.php?a=export" download>Télécharger une copie complète (JSON, non chiffrée)</a><p class="muted" style="font-size:.85rem">Cette copie contient des données de santé : conservez-la sur un support protégé et supprimez-la après usage. Le téléchargement est inscrit au journal d’audit.</p></div>';
  };
})();

